    expect(await ui.claimEditOpen(pg_uma, c_ada_2)).toBe(true);
    await ui.claimEditCancel(pg_uma, c_ada_2);
    expect(await ui.claimEditOpen(pg_uma, c_ada_0)).toBe(true);
    expect(await ui.claimEditOpen(pg_uma, c_ada_1)).toBe(false);
